'use strict';
const fs=require('node:fs');
const path=require('node:path');
const cp=require('node:child_process');
const zlib=require('node:zlib');
const crypto=require('node:crypto');
const root=path.join(__dirname,'.runtime');
const sha=s=>crypto.createHash('sha256').update(s).digest('hex');
try{
  fs.rmSync(root,{recursive:true,force:true});
  fs.mkdirSync(root,{recursive:true});
  const p1=fs.readFileSync(path.join(__dirname,'payload.part01'),'utf8');
  const p2=fs.readFileSync(path.join(__dirname,'payload.part02'),'utf8');
  const p3files=Array.from({length:6},(_,j)=>`payload.p03.${j+1}`);
  const p3parts=p3files.map(f=>fs.readFileSync(path.join(__dirname,f),'utf8'));
  const expected=['3c3392147d652cc9e3a8187982e50fa1711a379552f78a26deb9785efe5af3bc','1ae0b51a3e029539a0e9cb26040f6d9671eef9ac47e362b2f391b8c2343b3f2d','75db04bcc2a7167af2f63f1f787761f0141b9838c6ad9bca5dbeea5b9a221518','f4dcf0f46537a32fc563106537d67454d6e4c9f6addc5b90d9da01420f5403cb','63191f831b11bd6cea0172b8e2df1e3bbcc7fd9298640dcb96e2c8b516bfa119','e843aff784aceff9203a6b0a3d6f21a615b8d53e684498d99f3a43aabf5b4505'];
  p3parts.forEach((p,i)=>{const got=sha(p); console.log('P3_SEGMENT',i+1,p.length,got); if(got!==expected[i]) throw new Error(`payload.p03.${i+1} integrity mismatch`) });
  const p3=p3parts.join('');
  if(sha(p3)!=='c061fe82c8adad32486982422c521a027ee7dcf18ae2bbd37d68848eb2fc5c45') throw new Error('payload part03 combined integrity mismatch');
  const p4=fs.readFileSync(path.join(__dirname,'payload.part04'),'utf8');
  const b64=p1+p2+p3+p4;
  console.log('PAYLOAD_READY',b64.length,sha(b64));
  const br=Buffer.from(b64,'base64');
  const tar=zlib.brotliDecompressSync(br);
  const tarPath='/tmp/nextmove.tar';
  fs.writeFileSync(tarPath,tar);
  cp.execFileSync('tar',['-xf',tarPath,'-C',root],{stdio:'inherit'});
}catch(e){console.error('Bootstrap extraction failed',e);process.exit(1)}
const child=cp.spawn(process.execPath,['server.js'],{cwd:root,env:process.env,stdio:'inherit'});
child.on('exit',c=>process.exit(c??1));
process.on('SIGTERM',()=>child.kill('SIGTERM'));
process.on('SIGINT',()=>child.kill('SIGINT'));
